<template>
  <div class="option-container option-repeater">
    <repeater-preview
      :items="repeaterValues"
      :can-delete="repeaterValues.length > value.attributes.min"
      :item-label="itemLabel"
      :default-active-item-index="defaultActiveItemIndex"
      :can-set-default-active-index="canSetDefaultActiveIndex"
      @editItem="editItem"
      @deleteItem="removeItem"
      @change="changeOrder"
    />
    <div class="d-flex p-2 action-buttons">
      <button @click="openRepeaterEditor(true)" :title="addItemLabel" class="btn btn-sm btn-success mr-1 add-new" :disabled="repeaterValues.length >= value.attributes.max">
        <custom-icon icon="add" />
      </button>
      <button @click="openRepeaterEditor(false)" class="btn btn-sm btn-primary ml-1">
        <custom-icon icon="cog" custom-class="mr-2" />
        <span class="d-block" v-text="$t('editor.options.repeater.buttons.settings')" />
      </button>
    </div>

    <b-modal
      :noEnforceFocus="true"
      :noCloseOnBackdrop="true"
      :noCloseOnEsc="true"
      :visible="editRepeater"
      @hidden="cancelRepeaterEditor"
      centered
      no-fade
      :title="value.label || $t('editor.options.repeater.itemsLabel')"
      ref="repeaterModal"
      size="lg"
      modal-class="popup-modal repeater-modal"
    >
      <language-switcher />
      <div class="repeater__wrapper">
        <div class="repeater__tabs">
          <draggable
            v-model="repeaterList"
            @start="dragging = true"
            @stop="dragging = false"
            @change="$emit('change', $event)"
            group="repeaterValues"
            handle=".move-item"
            class="repeater__tabs--navigation"
          >
            <div
                v-for="(opt, oIndex) in repeaterList"
                :key="oIndex"
                class="repeater__tabs--navigation-item"
                :class="{ 'active-item': activeTab === oIndex }"
            >
              <button class="btn btn-transparent btn-sm move-item">
                <custom-icon icon="sort" />
              </button>

              <div @click="toggleActiveTab(oIndex)" class="title-wrapper">
                <span class="title">{{ opt[0].value[language] || 'Untitled' }}</span>
                <span class="d-block text-muted">{{ itemLabel }} #{{ oIndex + 1 }}</span>
              </div>
              <div class="ml-auto item-actions">
                <b-button v-if="canSetDefaultActiveIndex" @click="activeItem = oIndex" variant="link" class="btn-sm">
                  <custom-icon :icon="isActiveItem(oIndex) ? 'star' : 'star-outline'" height="14" />
                </b-button>

                <button
                  v-if="repeaterList.length > value.attributes.min"
                  @click="removeRow(oIndex)"
                  class="btn btn-danger btn-sm ml-1"
                >
                  <custom-icon icon="close" height="13" />
                </button>
              </div>
            </div>
          </draggable>
          <div class="repeater__tabs--content">
            <div
              class="repeater__item"
              v-for="(opt, oIndex) in repeaterList"
              :key="oIndex"
              :class="{ 'd-none': activeTab !== oIndex }"
            >
              <component
                :id="eachOpt.id"
                :is="eachOpt.type"
                :key="eachOpt.id"
                :label="eachOpt.label"
                :language="language"
                v-for="(eachOpt, index) in opt"
                v-model="opt[index]"
                @triggerSave="(value) => handleTriggerSave(value, eachOpt, index, oIndex)"
              ></component>
            </div>
          </div>
        </div>
      </div>
      <template slot="modal-footer">
        <div class="repeater__wrapper--footer clearfix">
          <button
            @click="addRow"
            class="btn btn-success btn-sm"
            :disabled="repeaterList.length >= value.attributes.max"
          >
            {{ addItemLabel }}
          </button>
          <div class="modal-actions">
            <button @click="cancelRepeaterEditor" class="btn btn-default btn-sm" v-text="$t('editor.options.repeater.buttons.cancel')" />
            <button @click="saveRepeaterEditor" class="btn btn-primary btn-sm ml-2" v-text="$t('editor.options.repeater.buttons.confirm')" />
          </div>
        </div>
      </template>
    </b-modal>
  </div>
</template>

<script>
import Options from "./Options";
import draggable from "vuedraggable";
import CustomIcon from "@/components/CustomIcon";
import RepeaterPreview from "@/components/editor/panel/options/repeaterPreview.vue";
import LanguageSwitcher from "@/components/editor/panel/LanguageSwitcher.vue";
export default {
  props: ["value"],
  extends: Options,
  components: {
    LanguageSwitcher,
    RepeaterPreview,
    draggable,
    CustomIcon,
  },
  data() {
    return {
      dragging: true,
      editRepeater: false,
      repeaterList: [],
      activeTab: 0,
      activeItem: this.value.attributes.defaultActiveIndex,
    };
  },
  computed: {
    language() {
      return this.$store.state.editor.currentLanguage;
    },

    addItemLabel() {
      return this.value.attributes.addMoreLabel ? this.value.attributes.addMoreLabel : this.$t('editor.options.repeater.buttons.addMoreLabel');
    },

    itemLabel() {
      return this.value.attributes.itemLabel ? this.value.attributes.itemLabel : this.$t('editor.options.repeater.itemLabel');
    },
    repeaterFields() {
      return this.value.fields;
    },
    repeaterValues: {
      get() {
        return this.value.value;
      },
      set(newValue) {
        this.value.value = newValue;
      },
    },
    canSetDefaultActiveIndex() {
      return this.value.attributes.canSetDefaultActiveIndex || false;
    },
    defaultActiveItemIndex: {
      get() {
        return this.value.attributes.defaultActiveIndex;
      },
      set(newValue) {
        this.value.attributes.defaultActiveIndex = newValue;
      },
    },
  },
  methods: {
    addRow() {
      let fields = JSON.parse(JSON.stringify(this.repeaterFields));

      fields.forEach((field) => {
        let uniqueID = field.id + "_" + Math.random().toString(36).substr(2, 9);
        field.repeaterField = field.id;
        field.id = uniqueID;
      });

      this.repeaterList.push(fields);

      this.activeTab = this.repeaterList.length - 1;
    },
    handleTriggerSave(value, option, optionIndex, parentIndex) {
      this.repeaterList[parentIndex][optionIndex] = option;
      this.$emit("triggerSave", this.repeaterList);
    },
    removeRow(index) {
      this.repeaterList.splice(index, 1);
      this.activeTab = this.repeaterList.length - 1;
      this.activeItem = 0;
    },
    removeItem(index) {
      this.repeaterValues.splice(index, 1);
      this.defaultActiveItemIndex = 0;
      this.activeItem = 0;
    },

    openRepeaterEditor(newTab) {
      this.repeaterList = JSON.parse(JSON.stringify(this.value.value));
      this.activeTab = 0;
      this.editRepeater = true;

      if(newTab) {
        this.addRow();
      }
    },

    saveRepeaterEditor() {
      this.repeaterValues = this.repeaterList;
      this.$emit('changeActiveItem', this.activeItem, this.repeaterList);
      this.editRepeater = false;
    },

    cancelRepeaterEditor() {
      this.repeaterList = [];
      this.editRepeater = false;
      this.activeItem = this.defaultActiveItemIndex;
    },

    toggleActiveTab(tab) {
      this.activeTab = tab;
    },

    editItem(item) {
      this.openRepeaterEditor();
      this.activeTab = item;
    },

    changeOrder(items) {
      this.repeaterValues = items;
    },

    isActiveItem(item) {
      return parseInt(this.activeItem) === item;
    }
  },
};
</script>

