<template>
  <div class="repeater__preview">
    <ul class="list-items">
      <draggable
          v-model="itemsList"
          group="repeaterValues"
          handle=".move-item"
      >
      <li v-for="(item, i) in itemsList" :key="i">
        <b-button variant="transparent" size="small" class="move-item">
          <custom-icon icon="sort" />
        </b-button>

        <div class="title-wrapper" @click="$emit('editItem', i)">
          <span class="title">{{ item[0].value[language] || 'Untitled' }}</span>
          <span class="d-flex align-items-center text-muted">
            {{ itemLabel }} #{{ i+1 }}
            <custom-icon v-if="defaultActiveItem === i && canSetDefaultActiveIndex" icon="star" color="#fdc300" width="14" height="14" custom-class="mt-n1 ml-1" />
          </span>
        </div>

        <div class="ml-auto">
          <b-button v-if="canDelete" @click="$emit('deleteItem', i)" variant="danger" class="btn-sm delete-item">
            <custom-icon icon="close" height="13" />
          </b-button>
        </div>
      </li>
    </draggable>
    </ul>
  </div>
</template>

<script>
import draggable from "vuedraggable";
import CustomIcon from "@/components/CustomIcon";
export default {
  props: ["items", "canDelete", "itemLabel", "defaultActiveItemIndex", "canSetDefaultActiveIndex"],
  components: {
    draggable,
    CustomIcon,
  },
  computed: {
    language() {
      return this.$store.state.editor.currentLanguage;
    },

    itemsList: {
      get() {
        return this.items;
      },
      set(newValue) {
        this.$emit('change', newValue);
      },
    },

    defaultActiveItem() {
      return parseInt(this.defaultActiveItemIndex);
    }
  }
};
</script>

